	// citing the trusted height 100, and a proof-at-101 message keeps waiting.
	submitMsg(t, state, "m100", "chain-a", "chain-b", 1, 100)
	rep := advanceCLI(t, state, 2_000)
	got := resultFor(t, rep, "m100")
