		got.Reason != "delivered; proof verified by trusted header at height 100" {
		t.Fatalf("covered message must deliver under trusted height 100: %+v", got)
	}
}

// A NUL byte and surrounding whitespace/case in a root are raw content too;
// they survive reopen and stay distinct.
func TestCLIHeaderRawRootNULAndSpacing(t *testing.T) {
	state := t.TempDir()
	registerSource(t, state, "chain-a")
	root := "r\x00" + "\xff"
	if r := storeHeader(t, state, "chain-a", 3, root, true); r.code != 0 {
		t.Fatalf("NUL/raw-byte root save: code=%d stderr=%q", r.code, r.stderr)
	}
	if r := storeHeader(t, state, "chain-a", 3, root, true); r.code != 0 {
		t.Fatalf("identical NUL/raw-byte root must resave: code=%d stderr=%q", r.code, r.stderr)
	}
	for _, other := range []string{"r\x00" + "\xfe", "R\x00" + "\xff", "r\x00" + "\xff ", ""} {
		assertHeaderConflict(t, storeHeader(t, state, "chain-a", 3, other, true),
			"chain-a", 3, other, root)
	}
	// Sanity: the height renders in the conflict message.
	if r := storeHeader(t, state, "chain-a", 3, "x", true); r.code != 16 ||
		!containsAll(r.stderr, "height "+strconv.FormatInt(3, 10)) {
		t.Fatalf("conflict must name height 3: code=%d stderr=%q", r.code, r.stderr)
	}
}

func containsAll(s string, wants ...string) bool {
	for _, w := range wants {
		if !contains(s, w) {
			return false
		}
	}
	return true
}

func contains(s, sub string) bool {
	return len(sub) == 0 || (len(s) >= len(sub) && indexOf(s, sub) >= 0)
}

func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}

