// One large pending payload pads the log to just below the 4 MiB
// compaction threshold; equal-time advance checkpoints (legal while time
// stands still) then cross it and trigger the automatic rewrite. A
// compaction atomically replaces the log with its snapshot, which is
// observable as a sudden size drop; loop only until that drop appears.
r := queueCLI(t, state, "submit",
	"--id", "filler", "--from", "chain-a", "--to", "chain-b",
	"--nonce", "42", "--proof-at", "100",
	"--payload", strings.Repeat("x", (4<<20)-2048),
	"--expires-at", "9000000000000",
)
if r.code != 0 {
	t.Fatalf("filler submit: code=%d stderr=%q", r.code, r.stderr)
}
maxSize := logSize(t, state)
compacted := false
for i := 0; i < 400; i++ {
	if cr := queueCLI(t, state, "advance", "--now", "1000"); cr.code != 0 {
		t.Fatalf("padding advance %d: code=%d stderr=%q", i, cr.code, cr.stderr)
	}
	size := logSize(t, state)
	if size > maxSize {
		maxSize = size
	}
	if size < maxSize-1024 {
		compacted = true
		break
	}
}
