	must(q.RegisterSource("a") == nil, "register")
	ff := string([]byte{0xFF})
	fe := string([]byte{0xFE})
	fffd := "�"

	must(q.UpsertHeader(relayproof.Header{Chain: "a", Height: 100, Root: ff, Trusted: true}) == nil, "save ff")
	// waiting message scheduled before later header saves
	_, err = q.Submit(relayproof.Envelope{Message: relayproof.Message{ID: "w", From: "a", To: "b", Nonce: 9, ProofAt: 101}})
	must(err == nil, "submit w")
	rep, err := q.Advance(1000)
	must(err == nil && rep.Results[0].Status == relayproof.StatusWaiting, "advance w: %v %+v", err, rep.Results)

	// trigger automatic compaction with a big payload + checkpoint padding
	_, err = q.Submit(relayproof.Envelope{Message: relayproof.Message{
		ID: "filler", From: "a", To: "b", Nonce: 8, ProofAt: 100,
		Payload: strings.Repeat("x", (4<<20)-8192),
	}})
	must(err == nil, "filler submit: %v", err)
	prev := int64(-1)
	for i := 0; i < 1000; i++ {
		_, err = q.Advance(1000)
		must(err == nil, "pad advance: %v", err)
		_ = prev
		if i > 0 {
			// size observed through closed reopen below; just break after threshold crossed by attempting many
		}
	}
	fmt.Println("checkpoint padding appended")

	// higher untrusted (fe) and lower trusted (fffd): must not replace accepted ff
	must(q.UpsertHeader(relayproof.Header{Chain: "a", Height: 120, Root: fe, Trusted: false}) == nil, "untrusted 120")
	must(q.UpsertHeader(relayproof.Header{Chain: "a", Height: 50, Root: fffd, Trusted: true}) == nil, "lower trusted 50")

	q.Close()
	q, err = relayproof.Open(dir)
	must(err == nil, "reopen: %v", err)

	// waiting message retry schedule untouched by header saves (retry at 2000, attempts 1)
	r, ok := q.Query("w")
	must(ok && r.Status == relayproof.StatusWaiting && r.Attempts == 1 && r.NextRetry == 2000,
		"waiting record changed: %+v", r)

	err = q.UpsertHeader(relayproof.Header{Chain: "a", Height: 100, Root: ff, Trusted: true})
	must(err == nil, "resave original ff after reopen+compaction: %v", err)
	err = q.UpsertHeader(relayproof.Header{Chain: "a", Height: 100, Root: fe, Trusted: true})
	must(errors.Is(err, relayproof.ErrHeaderConflict), "fe must conflict, got %v", err)
	err = q.UpsertHeader(relayproof.Header{Chain: "a", Height: 100, Root: fffd, Trusted: true})
	must(errors.Is(err, relayproof.ErrHeaderConflict), "U+FFFD must conflict, got %v", err)
	fmt.Printf("conflict error distinguishes roots: %v\n", err)

	// queue still processes under trusted coverage 100
	_, err = q.Submit(relayproof.Envelope{Message: relayproof.Message{ID: "m99", From: "a", To: "b", Nonce: 10, ProofAt: 99}})
	must(err == nil, "submit m99")
	rep, err = q.Advance(2000)
	must(err == nil, "advance 2000: %v", err)
	found := false
	for _, x := range rep.Results {
		if x.ID == "m99" {
			must(x.Status == relayproof.StatusSuccess && x.Reason == "delivered; proof verified by trusted header at height 100",
				"m99 wrong outcome: %+v", x)
			found = true
		}
	}
	must(found, "m99 not processed")
	q.Close()
	fmt.Println("MANUAL CHECK PASSED")
}

func removeAll(p string) error {
	// avoid importing os at top to keep snippet short; just use os below
	return osRemove(p)
}
